import numpy as np

demo_in = np.array(G['Demo pair 1 input'])
demo_out = np.array(G['Demo pair 1 output'])

print("Finding rectangular 3-regions with 2s inside:")

# Find connected components of 3s
visited = np.zeros(demo_in.shape, dtype=bool)
components = []

def find_component(r, c, grid, visited):
    if r < 0 or r >= grid.shape[0] or c < 0 or c >= grid.shape[1]:
        return []
    if visited[r, c] or grid[r, c] != 3:
        return []

    comp = [(r, c)]
    stack = [(r, c)]
    visited[r, c] = True

    while stack:
        cr, cc = stack.pop()
        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
            nr, nc = cr + dr, cc + dc
            if 0 <= nr < grid.shape[0] and 0 <= nc < grid.shape[1]:
                if not visited[nr, nc] and grid[nr, nc] == 3:
                    visited[nr, nc] = True
                    comp.append((nr, nc))
                    stack.append((nr, nc))

    return comp

for r in range(demo_in.shape[0]):
    for c in range(demo_in.shape[1]):
        if demo_in[r][c] == 3:
            component = find_component(r, c, demo_in, visited.copy())
            # Check if there are any 2s adjacent to this component
            has_2_adjacent = False
            for rr, rc in component:
                for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                    nr, nc = rr + dr, rc + dc
                    if 0 <= nr < demo_in.shape[0] and 0 <= nc < demo_in.shape[1]:
                        if demo_in[nr, nc] == 2:
                            has_2_adjacent = True
                            break
                if has_2_adjacent:
                    break

            if len(component) > 0:
                components.append(((r,c), component[:], has_2_adjacent))

# Show components with 2s adjacent
print(f"\nFound {len(components)} 3-components")
for orig_r, orig_c, (comp, has_2) in zip(components[:5], [], [(c[1], c[2]) for c in components]):
