import numpy as np

demo_in = np.array(G['Demo pair 1 input'])
demo_out = np.array(G['Demo pair 1 output'])

# Verify hypothesis: 3 -> 1 iff adjacent to 2
def apply_rule(grid):
    new_grid = grid.copy()
    for r in range(grid.shape[0]):
        for c in range(grid.shape[1]):
            if grid[r][c] == 3:
                # Check orthogonal neighbors for 2
                for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < grid.shape[0] and 0 <= nc < grid.shape[1]:
                        if grid[nr][nc] == 2:
                            new_grid[r][c] = 1
                            break
    return new_grid

result = apply_rule(demo_in)
matches = np.array_equal(result, demo_out)
print(f"Hypothesis matches: {matches}")

if not matches:
    diff = result != demo_out
    print("\nDifferences:")
    diffs = []
    for r in range(diff.sum(axis=1).nonzero()[0][:5].tolist()):
        for c in range(diff.shape[1]):
            if diff[r, c]:
                diffs.append(f"({r},{c}): {result[r,c]} vs {demo_out[r,c]}")
    print("\n".join(diffs[:20]))

