import numpy as np

demo_in = np.array(G['Demo pair 1 input'])
demo_out = np.array(G['Demo pair 1 output'])

# Hypothesis: 3 -> 1 iff diagonally or orthogonally adjacent to 2
def apply_rule(grid):
    new_grid = grid.copy()
    for r in range(grid.shape[0]):
        for c in range(grid.shape[1)):
            if grid[r][c] == 3:
                # Check all 8 neighbors for 2
                for dr in [-1, 0, 1]:
                    for dc in [-1, 0, 1]:
                        if dr == 0 and dc == 0:
                            continue
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < grid.shape[0] and 0 <= nc < grid.shape[1]:
                            if grid[nr][nc] == 2:
                                new_grid[r][c] = 1
                                break
                    if new_grid[r][c] == 1:
                        break
            # Also change 0 to 1 around 2s
            elif grid[r][c] == 0:
                for dr in [-1, 0, 1]:
                    for dc in [-1, 0, 1]:
                        if dr == 0 and dc == 0:
                            continue
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < grid.shape[0] and 0 <= nc < grid.shape[1]:
                            if grid[nr][nc] == 2:
                                new_grid[r][c] = 1
                                break
                    if new_grid[r][c] == 1:
                        break
    return new_grid

result = apply_rule(demo_in)
matches = np.array_equal(result, demo_out)
print(f"Hypothesis matches: {matches}")

