# Find distances from each 2
def manhattan_dist(r, c, target_r, target_c):
    return abs(r - target_r) + abs(c - target_c)

def chebyshev_dist(r, c, target_r, target_c):
    return max(abs(r - target_r), abs(c - target_c))

# Check what patterns match 1-cells
