max_manhattan = 0
for r in range(demo_out.shape[0)):
    for c in range(demo_out.shape[1)):
        if is_one[r,c]:
            min_dist = float('inf')
            for tr, tc in twos:
                d = manhattan_dist(r, c, tr, tc)
                min_dist = min(min_dist, d)
            max_manhattan = max(max_manhattan, min_dist)

print(f"Max Manhattan distance observed: {max_manhattan}")

