def bfs_diagonal_from_start(start_r, start_c, grid):
    visited = set()
    stack = [(start_r, start_c)]
    while stack:
        r,c = stack.pop()
        if (r,c) in visited or not (0 <= r < rows and 0 <= c < cols):
